TLM.f("Sancti/12-21",{"officium":"S. Thomæ Apostoli","rule":["Gloria","Credo","Prefatio=Apostolis"],"sections":{"Introitus":[{"k":"ref","la":"Ps 138:17"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."},{"k":"ref","la":"Ps 138:1-2"},{"k":"text","la":"Dómine, probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."}],"Oratio":[{"k":"text","la":"Da nobis, quǽsumus, Dómine, beáti Apóstoli tui Thomæ sollemnitátibus gloriári: ut ejus semper et patrocíniis sublevémur; et fidem cóngrua devotióne sectémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Ephésios."},{"k":"ref","la":"Ephes 2:19-22"},{"k":"text","la":"Fratres: Jam non estis hóspites et ádvenæ: sed estis cives sanctórum et doméstici Dei: superædificáti super fundaméntum Apostolórum et Prophetárum, ipso summo angulári lápide Christo Jesu: in quo omnis ædificátio constrúcta crescit in templum sanctum in Dómino, in quo et vos coædificámini in habitáculum Dei in Spíritu."}],"Graduale":[{"k":"ref","la":"Ps 138:17-18"},{"k":"text","la":"Nimis honorati sunt amíci tui, Deus: nimis confortátus est principátus eórum."},{"k":"text","la":"Dinumerábo eos, et super arénam multiplicabúntur. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Gaudéte, justi, in Dómino: rectos decet collaudátio. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Gaudéte, justi, in Dómino: rectos decet collaudátio. Allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem."},{"k":"ref","la":"Joann 20:24-29"},{"k":"text","la":"In illo témpore: Thomas, unus ex duódecim, qui dícitur Dídymus, non erat cum eis, quando venit Jesus. Dixérunt ergo ei alii discípuli: Vídimus Dóminum. Ille autem dixit eis: Nisi videro in mánibus ejus fixúram clavórum, et mittam dígitum meum in locum clavórum, et mittam manum meam in latus ejus, non credam. Et post dies octo, íterum erant discípuli ejus intus, et Thomas cum eis. Venit Jesus jánuis clausis, et stetit in médio, et dixit: Pax vobis. Deinde dicit Thomæ: Inter dígitum tuum huc, et vide manus meas, et affer manum tuam, et mitte in latus meum: et noli esse incrédulus, sed fidélis. Respóndit Thomas et dixit ei: Dóminus meus et Deus meus. Dixit ei Jesus: Quia vidisti me, Thoma, credidísti: beáti, qui non vidérunt, et credidérunt."}],"Offertorium":[{"k":"ref","la":"Ps 18:5"},{"k":"text","la":"In omnem terram exívit sonus eórum: et in fines orbis terræ verba eórum."}],"Secreta":[{"k":"text","la":"Débitum tibi, Dómine, nostræ réddimus servitútis, supplíciter exorántes: ut, suffrágiis beáti Thomæ Apóstoli, in nobis tua múnera tueáris, cujus honoránda confessióne laudis tibi hóstias immolámus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joannes 20:27"},{"k":"text","la":"Mitte manum tuam, et cognósce loca clavórum(, allelúja): et noli esse incrédulus, sed fidélis(, allelúja, allelúja)."}],"Postcommunio":[{"k":"text","la":"Adésto nobis, miséricors Deus: et, intercedénte pro nobis beáto Thoma Apóstolo, tua circa nos propitiátus dona custódi."},{"k":"macro","name":"Per Dominum"}]},"hr":{"4ce2969ae90d1d66":{"t":"Ps 138, 17, Ps 138, 1-2\n(Ps 138, 17) Nadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove. (Ps 138, 1-2) Gospodine, ti si me kušao i spoznao, tebi je poznat moj počinak i moje uskrsnuće.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 138, 17) Nadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove.","kn":"(Ps. 138, 17). Veoma častim prijatelje Tvoje, Bože, silno je utvrđeno kneževstvo njihovo. (Ps. 133, 1). Gospodine, Ti sj me kušao i spoznaoi; Tebi je poznat moj počinak i moje ustajanje. Slava Ocu . . . Veoma ...","knRef":"Kniewald 1942, str. 458–459 (snimka 230) (OCR)"},"f544f66e8c83520b":{"t":"<i>Pomolimo se</i>.\nDaj nam, molimo, Gospodine, da dostojno slavimo svetkovinu tvoga blaženog apostola Tome, da nas i njegova zaštita vazda uzdiže i da nasljedujemo njegovu vjeru prikladnom pobožnošću.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Daj nam, molimo. Gospodine, da dostojno slavimo svetkovinu blaženoga Tvoga apostola Tome, te nas i njegova zaštita vazda uzdizala, i mi nasljedovali njegovu vjeru prikladnom pobožnošču, po G. n.","knRef":"Kniewald 1942, str. 458–459 (snimka 230) (OCR)"},"60ea4869cf3aad30":{"t":"Ef 2, 19-22\nČitanje Poslanice bl. Pavla apostola Efežanima. Braćo: Više niste stranci ni pridošlice, nego ste sugrađani svetaca i Božji ukućani. Nazidni ste na temelju apostola i proroka, n ugaoni je kamen sam Isus Krist. Sva zgrada sazidana na njemu diže se za sveti hram u Gospodinu. Na njega se i vi nazidajte u Duhu za stan Božji.","kn":"Čitanje poslanice bi. Pavla apostola Efežanima (2, 19-22). Braćo! Više nijeste stranci ni prldošlice, nego ste sugrađani, svetaca i Božji ukućani. Nazidaini ste na temelj apostola i proroka, a ugaoni je kamen sam Isus Krist. Sva zgrada sazidana na njemu diže se za sveti hram u Gospodinu. Na njega se i vi nazidajte u Duhu za stan Božji.","knRef":"Kniewald 1942, str. 458–459 (snimka 230) (OCR)"},"bbeb958771bc7de1":{"t":"Ps 138, 17-18\nNadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove. Da ih brojim, ima ih više nego pijeska.\n\nPs 32, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nRadujte se pravednici u Gospodinu, pravednima dolikuje pohvala. <i>Aleluja</i>.","kn":"(Pe. 138, 17). Veoma častim prijatelje Tvoje, Bože, veoma se utvrdi kneževstvo njihovo. Da ih brojim, više ih je nego pijeska.\n\nAleluja, aleluja. (Ps. 33, 11). Radujte se pravednici u Gospodinu, pravednima dolikuje pohvala. Alelujia.","knRef":"Kniewald 1942, str. 458–459 (snimka 230) (OCR)"},"53028b633897e994":{"t":"Iv 20, 24-29\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme: Toma Blizanac, jedan od dvanaestorice, nije bio s njima kad je došao Isus. Drugi mu učenici reknu: Vidjesmo Gospodina. A on im odgovori: Neću vjerovati dok ne vidim na njegovim rukama rana od čavala i ne metnem svoga prsta u mjesto od. čavala i ne metnem svoje ruke u njegov bok. I poslije osam dana bili su opet njegovi učenici unutra i s njima Toma. Isus dođe, dok su vrata bila zatvorena, stade u sredinu i reče: Mir vama! Zatim kaže Tomi: Metni ovamo svoj prst i vidi moje ruke i pruži svoju ruku i metni u moj bok. I ne budi nevjeran nego vjeran. Toma odgovori; Gospodine moj i Bože moj! Isus mu reče: Povjerovao si, Toma, kad si me vidio. Blago onima koji ne vide a vjeruju!","kn":"t Slijedi sveto evanđelje po Ivanu (20, 24-29). U ono vrijeme Toma Blizanac, jedan od dvanaestorice, nije bio s njima, kad je došao Isus. Drugi mu učenici reknu: Vidjesmo Gospodina. A on im odgovori: Ne ću vjerovati, dok ne vidim na njegovimrukama rana o-d čavala 1 ne metnem svoga prsta u mjesto od čavala i ne metnem svoje ruke u njegov b-ok. I poslije osam dana bili su opet njegovi učeniici unutra i s njima Toma. Isus dođe, dok su vrata bila zatvorena, stade u sredinu i reče: Mir vama! Zatim kaže Toma: Metni ovamo svoj prst, ; vidi moje ruke, i pruži svoju ruku i metni r U moj bok, i ne budi nevjeran, nego vjeran. Toma odgovori: Gospodine moj i Bože moj! Isus mu reče: Povjerovao si, kad si me vidio. Blago omima, koji ne vide, a vjeruju!","knRef":"Kniewald 1942, str. 458–459 (snimka 230) (OCR)"},"cb52094c85d2a3b5":{"t":"Ps 18, 5\nPo svoj zemlji iziđe njihov glas i do na kraj svijeta nauka njihova.","kn":"(Ps. 18, 5). Po svoj zemlji iziđe glas njihov i do na kraj zemlje riječi njihove.","knRef":"Kniewald 1942, str. 656–657 (snimka 329) (OCR)"},"534846b11f503202":{"t":"Donosimo ti, Gospodine, dugovanje svoje službe smjerno te moleći da u nama sačuvaš svoje darove po zagovoru blaženog apostola Tome, a radi njegova časnog priznanja prinosimo ti žrtve zahvalnice.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Plaćamo Ti, Gospodine, dugovanje svoje službe smjerno te moleći, da u nama sačuvaš svoje darove po zagovoru blaženoga apostola Tome, kojega časno ispovijedajući prinosimo Ti žrtve pohvalnice. Po G. n.","knRef":"Kniewald 1942, str. 460–461 (snimka 231) (OCR)"},"fdbfd5e8960de5c2":{"t":"Uistinu je dostojno, i pravedno, pravo i spasonosno tebe, Gospodine, vječni Pastiru, smjerno moliti da stado svoje ne ostaviš, nego da ga po svojim blaženim apostolima neprestano štitiš i čuvaš, da njime ravnaju isti poglavari, koje si mu postavio na čelo kao pastire i namjesnike svoga djela. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno. Tebe, Gospodine, vječni Pastiru, smjerno moliti, da ne ostaviš svoga stada, nego’ da ga po blaženim svojim apostolima sveudiljnom zaštitom čuvaš, te Tvojim stadom upravljaju isti vođe, koje si Ti odredio da ga vode kao pastiri i namjesnici Tvoga djelovanja. I toga radi pjevamo pjesmu slave Tvoje s anđelima i s arkanđelima, s prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 618–619 (snimka 310) (OCR)"},"6cd81dcf984723b5":{"t":"Iv 20, 27\nPruži ruku svoju i upoznaj mjesto čavala i ne budi nevjeran nego vjeran.","kn":"(Iv. 20, 27). Pruži ruku svoju i upoznaj mjesta od čavala i ne budi nevjeran, nego vjeran, aleluja, aleluja.","knRef":"Kniewald 1942, str. 318–319 (snimka 160) (OCR)"},"7c5307ca36e742e8":{"t":"<i>Pomolimo se</i>.\nPriteci nam u pomoć, milostivi Bože, i po zagovoru blaženoga Tome apostola čuvaj milostivo u nama svoje darove.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Priteci nam u pomoć milostivi Bože, i odvjetovanjem blaženoga Tome, apostola, čuvaj milostivo u nama svoje darove. Po G. n.","knRef":"Kniewald 1942, str. 460–461 (snimka 231) (OCR)"}}});
